return $input.all().map((item, index) => {
  const row = item.json;

  // Cerca la colonna per nome esatto oppure per parola chiave (fuzzy match)
  const getField = (rowObj, possibleNames, keywords = []) => {
    const keys = Object.keys(rowObj);

    // 1. Corrispondenza esatta
    for (const name of possibleNames) {
      const foundKey = keys.find(k => k.trim().toLowerCase() === name.toLowerCase());
      if (foundKey && rowObj[foundKey] !== undefined && rowObj[foundKey] !== null && rowObj[foundKey].toString().trim() !== '') {
        return rowObj[foundKey];
      }
    }

    // 2. Fallback su parole chiave (es. 'desc', 'caus', 'operaz')
    for (const kw of keywords) {
      const foundKey = keys.find(k => k.toLowerCase().includes(kw.toLowerCase()));
      if (foundKey && rowObj[foundKey] !== undefined && rowObj[foundKey] !== null && rowObj[foundKey].toString().trim() !== '') {
        return rowObj[foundKey];
      }
    }

    return '';
  };

  const parseAmount = (val) => {
    if (!val || val.toString().trim() === '' || val === 'undefined') return 0;
    const cleanStr = val.toString().replace(/\./g, '').replace(',', '.');
    return parseFloat(cleanStr) || 0;
  };

  const rawData = getField(row, ['DATA', 'Data', 'Data operazione', 'Data Contabile'], ['data']).toString().trim();

  const rawDesc = getField(
    row, 
    ['DESCRIZIONE', 'Descrizione', 'Causale', 'Descrizione operazione', 'Descrizione estesa', 'Operazione', 'Dettagli', 'Causale ABI'],
    ['desc', 'caus', 'operaz', 'dettagl']
  ).toString().trim();

  const rawDivisa = (getField(row, ['DIVISA', 'Divisa', 'Valuta'], ['divisa', 'valuta']) || 'EUR').toString().trim();

  const dare = parseAmount(getField(row, ['DARE', 'Dare']));
  const avere = parseAmount(getField(row, ['AVERE', 'Avere']));
  const importoSingolo = parseAmount(getField(row, ['IMPORTO', 'Importo']));

  let importoCalcolato = 0;
  if (avere !== 0 || dare !== 0) {
    importoCalcolato = avere > 0 ? avere : -dare;
  } else {
    importoCalcolato = importoSingolo;
  }

  // Previene errori di sintassi SQL sanitizzando gli apostrofi (es. MC DONALD'S -> MC DONALD''S)
  const descClean = rawDesc.replace(/'/g, "''");

// L'aggiunta di index rende univoca ogni riga anche in caso di pagamenti identici nello stesso giorno
  const hashBase = `${rawData}_${rawDivisa}_${rawDesc}_${importoCalcolato}_${index}`;

  return {
    json: {
      data: rawData,
      descrizione: rawDesc,
      descrizione_clean: descClean,
      divisa: rawDivisa,
      importo: importoCalcolato,
      hash_base: hashBase
    }
  };
});

const countMap = {};

return $input.all().map(item => {
  const rawDesc = item.json.descrizione || '';
  const testo = rawDesc.toUpperCase();

  // 1. Regole fisse di pre-categorizzazione (esempi generici, da personalizzare)
  const regole = [
    ['Spesa / Alimentari', ['SUPERMERCATO', 'SUPERMARKET', 'ALIMENTARI']],
    ['Giroconto', ['GIROCONTO']],
    ['Utenze / Bollette', ['UTENZA', 'ENERGIA', 'TELEFONICA']],
    ['Entrate / Stipendio', ['EMOLUMENTI', 'STIPENDIO']],
    ['Auto', ['DISTRIBUTORE', 'CARBURANTE']],
    ['Shopping', ['ABBIGLIAMENTO', 'NEGOZIO']],
    ['Prelievi / Contanti', ['PRELIEVO', 'ATM', 'BANCOMAT', 'SPORTELLO']]
  ];
  let categoria = "Altro";
  for (const [nome, parole] of regole) {
    if (parole.some(p => testo.includes(p))) { categoria = nome; break; }
  }

  // 2. Mascheramento dati sensibili (IBAN, Carte, CF, Date, Ore)
  let descMasked = rawDesc
    .replace(/IT\d{2}[A-Z]\d{10}[0-9A-Z]{12}/gi, '[IBAN]')
    .replace(/\b\d{4,6}\*+\d{3,4}\b|\b\d{12,16}\b/g, '[CARTA/CODICE]')
    .replace(/[A-Z]{6}\d{2}[A-Z]\d{2}[A-Z]\d{3}[A-Z]/gi, '[CODICE_FISCALE]')
    .replace(/\b\d{1,2}[\/\.-]\d{1,2}[\/\.-]\d{2,4}\b|\b\d{4}[\/\.-]\d{1,2}[\/\.-]\d{1,2}\b/g, '[DATA]')
    .replace(/\b([01]?\d|2[0-3])[:.][0-5]\d([:.][0-5]\d)?\b/g, '[ORA]');

  // 3. Pulizia diciture bancarie ridondanti sulla stringa mascherata
  let cleanDesc = descMasked
    .replace(/PAGAMENTO\s+P\.O\.S\./gi, '')
    .replace(/DATA\/ORA:?\s*\[?DATA\]?\s*\[?ORA\]?/gi, '')
    .replace(/DATA\/ORA:?\s*/gi, '')
    .replace(/CARTA\s+N\.\s*\[?CARTA\/CODICE\]?/gi, '')
    .replace(/MAESTRO|VISA|MASTERCARD/gi, '')
    .replace(/\s+/g, ' ')
    .trim();

  const descrizioneFinale = cleanDesc || descMasked || rawDesc;

  // 4. Calcolo Firma e Occorrenza
  const divisa = item.json.divisa || 'EUR';
  const signature = `${item.json.data}_${divisa}_${descrizioneFinale}_${item.json.importo}`;
  countMap[signature] = (countMap[signature] || 0) + 1;
  const occurrence = countMap[signature];

  // 5. Sanitizzazione SQL e generazione hash_base univoco
  const descCleanSQL = descrizioneFinale.replace(/'/g, "''");
  const hashBase = `${item.json.data}_${divisa}_${descrizioneFinale}_${item.json.importo}_${occurrence}`;

  return {
    json: {
      ...item.json,
      descrizione: descrizioneFinale,
      descrizione_clean: descCleanSQL,
      categoria_ai: categoria,
      occurrence: occurrence,
      hash_base: hashBase
    }
  };
});

const categorie = [
  'alimentari', 'ristoranti', 'trasporti', 'salute', 
  'casa', 'svago', 'servizi', 'stipendio', 'shopping', 'auto', 'utenze', 'prelievi'
];

return $input.all().map((item) => {
  // SE la categoria è già stata assegnata dal primo nodo e non è "Altro", LA MANTIENE
  if (item.json.categoria_ai && item.json.categoria_ai !== 'Altro') {
    return {
      json: item.json
    };
  }

  // ALTRIMENTI legge la risposta di Ollama per le transazioni non riconosciute
  const risposta = (item.json.response || '').toLowerCase().trim();
  let categoriaFinale = 'Altro';

  for (const cat of categorie) {
    if (risposta.includes(cat)) {
      categoriaFinale = cat.charAt(0).toUpperCase() + cat.slice(1);
      break;
    }
  }

  return {
    json: {
      ...item.json,
      categoria_ai: categoriaFinale
    }
  };
});
